mapper.select:
SELECT * FROM ( SELECT OCODE OCODE, OTYPE OTYPE, GRADEORGID GRADEORGID, GRADEDATE GRADEDATE, NOTICEDATE NOTICEDATE, SHORTLONGTERM SHORTLONGTERM, MSTRATINGRESULT01 GRADERESULT,
MSTRATINGRESULT01 MSTRATINGRESULT01,
MSTRATINGRESULT02 MSTRATINGRESULT02,
INPUTTYPE INPUTTYPE, GRADEEXPECTATION GRADEEXPECTATION, DIRECTIONCHANGE DIRECTIONCHANGE, ISSUERRATETYPE ISSUERRATETYPE, rank() over (partition by OCODE,OTYPE,GRADEORGID order by GRADEDATE desc) rk FROM view_fin_product_rating where 1=1
AND OCODE = #{oCode,jdbcType=VARCHAR}
AND GRADEORGID = #{gradeOrgId,jdbcType=VARCHAR}
AND GRADEDATE <= STR_TO_DATE(#{gradeDate,jdbcType=VARCHAR}, '%Y-%m-%d')
AND GRADEDATE >= STR_TO_DATE(#{gradeDateStart,jdbcType=VARCHAR}, '%Y-%m-%d')
AND GRADEDATE <= STR_TO_DATE(#{gradeDateEnd,jdbcType=VARCHAR}, '%Y-%m-%d')
AND INNEROUTER = #{gradeSourceType,jdbcType=VARCHAR}
AND shortLongTerm = #{shortLongTerm,jdbcType=VARCHAR}
AND oType = #{oType,jdbcType=VARCHAR}
) WHERE 1=1
AND rk = 1

SELECT TEMP.* FROM ( SELECT * FROM ( SELECT OCODE OCODE, OTYPE OTYPE, GRADEORGID GRADEORGID, GRADEDATE GRADEDATE, NOTICEDATE NOTICEDATE, SHORTLONGTERM SHORTLONGTERM, MSTRATINGRESULT01 GRADERESULT,
MSTRATINGRESULT01 MSTRATINGRESULT01,
MSTRATINGRESULT02 MSTRATINGRESULT02,
INPUTTYPE INPUTTYPE, GRADEEXPECTATION GRADEEXPECTATION, DIRECTIONCHANGE DIRECTIONCHANGE, ISSUERRATETYPE ISSUERRATETYPE, rank() over (partition by OCODE,OTYPE,GRADEORGID order by GRADEDATE desc) rk FROM view_fin_product_rating where 1=1
AND OCODE = #{oCode,jdbcType=VARCHAR}
AND GRADEORGID = #{gradeOrgId,jdbcType=VARCHAR}
AND GRADEDATE <= STR_TO_DATE(#{gradeDate,jdbcType=VARCHAR}, '%Y-%m-%d')
AND GRADEDATE >= STR_TO_DATE(#{gradeDateStart,jdbcType=VARCHAR}, '%Y-%m-%d')
AND GRADEDATE <= STR_TO_DATE(#{gradeDateEnd,jdbcType=VARCHAR}, '%Y-%m-%d')
AND INNEROUTER = #{gradeSourceType,jdbcType=VARCHAR}
AND oType = #{oType,jdbcType=VARCHAR}
) WHERE 1=1
AND rk = 1
)
${sqlSortString}
